import math
from itertools import permutations

def is_perfect_square(k):
    if k < 0:
        return False
    sqrt_k = int(math.sqrt(k))
    return sqrt_k * sqrt_k == k

def is_cool_check(n):
    """
    Checks if n is a cool integer using a recursive backtracking approach.
    """
    numbers = list(range(1, n + 1))

    def solve(current_sum, used_mask, count):
        if count == n:
            # Successfully placed all n elements without hitting a square sum
            return True

        for i in range(n):
            if not (used_mask & (1 << i)):
                x = numbers[i]
                new_sum = current_sum + x

                # Check if the new prefix sum is a perfect square
                if is_perfect_square(new_sum):
                    continue

                # Recurse
                new_mask = used_mask | (1 << i)
                if solve(new_sum, new_mask, count + 1):
                    return True

        # No path worked from this state
        return False

    # Start the search: sum=0, mask=0, count=0
    return solve(0, 0, 0)

# Test for n = 1 to 15
results = {}
for n in range(1, 16):
    try:
        is_cool = is_cool_check(n)
        results[n] = "Cool" if is_cool else "Not Cool"
    except RecursionError:
        results[n] = "Error (Time/Memory Limit)"

print("N | Status")
print("-" * 15)
for n in sorted(results.keys()):
    print(f"{n:2} | {results[n]}")
